// Récupérer les descriptions de Gemini
const reponse = $input.first().json.candidates[0].content.parts[0].text;
const geminiData = JSON.parse(reponse.replace(/```json|```/g, '').trim());

// Récupérer les événements Ticketmaster
const evenements = $('Aggregate').first().json.evenements;
const style = $('Field Mapping').first().json['Style'] || 'All styles';
const categorie = $('Field Mapping').first().json['Category'];
const ville = $('Field Mapping').first().json['City'];

// Fusionner les deux sources
const eventsHTML = evenements.map((event, i) => {
  const description = geminiData.evenements[i]?.description || '';

  return `
  <div style="margin-bottom: 40px; border-bottom: 1px solid #e0d6c8; padding-bottom: 40px;">
    <img src="${event.image}" alt="${event.titre}"
      onerror="this.style.display='none'"
      style="width: 100%; max-height: 250px; object-fit: cover; margin-bottom: 16px;">
    <h2 style="font-family: Georgia, serif; font-size: 20px; color: #1a1a1a; margin: 0 0 4px 0;">
      ${event.titre}
    </h2>
    <p style="font-family: Georgia, serif; font-size: 13px; color: #7a6a5a; margin: 0 0 12px 0;">
      ${event.lieu} — ${event.adresse} — ${event.dates}
    </p>
    <p style="font-family: Georgia, serif; font-size: 15px; color: #333; line-height: 1.7; margin: 0 0 16px 0;">
      ${description}
    </p>
    <a href="${event.lien}"
      style="font-family: Georgia, serif; font-size: 13px; color: #6b2737; text-decoration: underline;">
      Voir l'événement
    </a>
  </div>
`}).join('');

const html = `
<div style="max-width: 600px; margin: 0 auto; background: #fff; padding: 40px 32px;">
  <h1 style="font-family: Georgia, serif; font-size: 26px; color: #1a1a1a;
    border-bottom: 2px solid #6b2737; padding-bottom: 16px; margin-bottom: 8px;">
    Sélection culturelle
  </h1>
  <p style="font-family: Georgia, serif; font-size: 13px; color: #7a6a5a; margin: 0 0 40px 0;">
    ${ville} — ${categorie} — ${style}
  </p>
  ${eventsHTML}
  <p style="font-family: Georgia, serif; font-size: 12px; color: #aaa;
    border-top: 1px solid #e0d6c8; padding-top: 24px; margin-top: 8px;">
    Sélection générée le ${ new Date().toLocaleDateString('fr-FR') }
  </p>
</div>
`;

return [{ json: { 
  html, 
  email: $('Field Mapping').first().json['Email']
}}];

const events = $input.first().json._embedded?.events || [];

// Dédupliquer par titre
const seen = new Set();
const unique = events.filter(event => {
  if (seen.has(event.name)) return false;
  seen.add(event.name);
  return true;
});

// Garder seulement les 5 premiers
const top5 = unique.slice(0, 5);

return top5.map(event => ({
  json: {
    titre: event.name,
    dates: event.dates?.start?.localDate || 'Dates not specified',
    lieu: event._embedded?.venues?.[0]?.name || 'Venue not specified',
    adresse: event._embedded?.venues?.[0]?.address?.line1 || '',
    ville: event._embedded?.venues?.[0]?.city?.name || '',
    lien: event.url || '',
    image: event.images?.[0]?.url || '',
    categorie: $('Field Mapping').first().json['Category'],
    style: $('Field Mapping').first().json['Style'] || 'all styles'
  }
}));

const evenements = $input.first().json.evenements;
const style = $('Field Mapping').first().json['Style'] || 'all styles';
const categorie = $('Field Mapping').first().json['Category'];

const liste = evenements.map((e, i) => 
  `${i+1}. Title: ${e.titre} | Venue: ${e.lieu} | Address: ${e.adresse} | City: ${e.ville} | Dates: ${e.dates}`
).join('\n');

return [{ json: { liste, style, categorie } }];
